.fg-wrap {
  max-width: 940px;
  margin: 0 auto;
  padding: 8px;
  font-family: Helvetica, Arial, sans-serif;
  color: #2b2118;
}
.fg-hero {
  padding: 18px 4px 14px;
}
.fg-hero h1 {
  font-size: 22px;
  margin: 0 0 8px;
  letter-spacing: -0.4px;
}
.fg-hero p {
  font-size: 14px;
  line-height: 1.6;
  color: #6b5a4a;
  margin: 0;
}
.fg-card {
  background: #fff;
  border: 1px solid #ece3d8;
  border-radius: 12px;
  padding: 16px;
  box-shadow: 0 2px 10px rgba(60, 42, 25, 0.07);
  box-sizing: border-box;
}

/* The drop target. It is the whole left column, so the gesture has a big
     forgiving area rather than a small button. */
.fg-top {
  display: grid;
  grid-template-columns: minmax(0, 260px) 1fr;
  gap: 20px;
  align-items: stretch;
}
.fg-drop {
  border: 2px dashed #ddcdb6;
  border-radius: 10px;
  background: #fffdf9;
  padding: 16px;
  text-align: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  transition:
    border-color 0.15s ease,
    background 0.15s ease;
  cursor: pointer;
}
.fg-drop.is-over {
  border-color: #c77b30;
  background: #fdf3e3;
}
.fg-drop b {
  font-size: 14px;
  color: #2b2118;
}
.fg-drop span {
  font-size: 12.5px;
  color: #7d6a58;
  line-height: 1.55;
}
.fg-or {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #a5947f;
}
.fg-paste {
  width: 100%;
  box-sizing: border-box;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  line-height: 1.5;
  border: 1px solid #e6dccd;
  border-radius: 6px;
  padding: 6px 8px;
  resize: vertical;
  min-height: 54px;
  color: #4a3a2a;
  background: #fff;
}
.fg-graphic {
  min-width: 0;
}
#chart {
  padding: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
  width: 100%;
}

.fg-presets {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 4px 0 0;
}
.fg-presets .fg-lab {
  font-size: 12px;
  color: #7d6a58;
}
.fg-chipbtn {
  border: 1px solid #e0d5c6;
  background: #fff;
  color: #5b4a38;
  border-radius: 999px;
  padding: 3px 11px;
  font-size: 12.5px;
  cursor: pointer;
}
.fg-chipbtn.is-active {
  background: #c77b30;
  border-color: #c77b30;
  color: #fff;
}

/* Controls: the documented options, as knobs. */
.fg-controls {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px 18px;
  border-top: 1px solid #f0e8dd;
  margin-top: 14px;
  padding-top: 14px;
}
.fg-ctl label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: #97836c;
  margin-bottom: 5px;
}
.fg-ctl label code {
  text-transform: none;
  letter-spacing: 0;
  font-size: 11.5px;
  color: #8a5a20;
}
.fg-ctl input[type='range'] {
  width: 100%;
  accent-color: #c77b30;
}
.fg-ctl select {
  width: 100%;
  font-size: 13px;
  padding: 4px 6px;
  border: 1px solid #e0d5c6;
  border-radius: 6px;
  background: #fff;
  color: #4a3a2a;
}
.fg-seg {
  display: flex;
  gap: 0;
}
.fg-seg button {
  flex: 1;
  border: 1px solid #e0d5c6;
  background: #fff;
  color: #5b4a38;
  font-size: 12.5px;
  padding: 5px 4px;
  cursor: pointer;
}
.fg-seg button:first-child {
  border-radius: 6px 0 0 6px;
}
.fg-seg button:last-child {
  border-radius: 0 6px 6px 0;
  border-left: 0;
}
.fg-seg button.is-active {
  background: #fdf3e3;
  border-color: #c77b30;
  color: #8a5a20;
  font-weight: 600;
}
/* A control group that cannot apply to the current mark. Dimmed AND inert,
     because a live control that silently does nothing is worse than none. */
.fg-seg.is-off {
  opacity: 0.4;
  pointer-events: none;
}
.fg-val {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  color: #2b2118;
}

/* The readout: what the packer actually did with the outline. */
.fg-readout {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid #f0e8dd;
  font-size: 12.5px;
  color: #6b5a4a;
}
.fg-readout b {
  color: #2b2118;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.fg-warn {
  margin-top: 12px;
  background: #fff6e8;
  border-left: 3px solid #d98324;
  border-radius: 2px;
  padding: 9px 13px;
  font-size: 12.5px;
  line-height: 1.6;
  color: #6b4a1e;
}
.fg-warn.is-bad {
  background: #fdedea;
  border-left-color: #c0442b;
  color: #7a2f1d;
}
.fg-hide {
  display: none;
}

/* The emitted snippet. */
.fg-code {
  margin: 18px 0 0;
  background: #2b2118;
  color: #f4ece0;
  border-radius: 10px;
  padding: 14px 16px;
  overflow-x: auto;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  line-height: 1.65;
  white-space: pre;
}
.fg-code .c {
  color: #a89b88;
}
.fg-code .s {
  color: #e8b87d;
}
.fg-codehead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 22px 4px 0;
}
.fg-codehead h2 {
  font-size: 15px;
  margin: 0;
}
.fg-copy {
  border: 1px solid #e0d5c6;
  background: #fff;
  color: #5b4a38;
  border-radius: 8px;
  padding: 4px 12px;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
}
.fg-note {
  background: #fdf7ee;
  border-left: 3px solid #c77b30;
  padding: 12px 16px;
  font-size: 13px;
  color: #4a3a2a;
  border-radius: 2px;
  line-height: 1.65;
  margin: 22px 4px 30px;
}
.fg-note code {
  background: #f5e7d3;
  padding: 1px 5px;
  border-radius: 3px;
}
.fg-note b {
  color: #2b2118;
}

@media (max-width: 560px) {
  .fg-top {
    grid-template-columns: 1fr;
  }
}
